name: Synthetic dynamic status
on: {tool_result: null}
decisions:
  review:
    input: {value: '${{ message.kind }}'}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions:
  - type: status
    input:
      result: ${{ decisions.review.outputs.verdict == 'yes' && 'success' || 'failure' }}
      message: "Selected: ${{ decisions.review.outputs.verdict }}"

