actions: [{type: status, input: {result: success}}]

name: Synthetic undeclared local decision condition
on: {tool_result: null}
actions:
  - type: status
    if: false && decisions.review.outputs.verdict == 'yes'
    input: {result: success}

name: Synthetic undeclared local decision message
on: {tool_result: null}
actions:
  - type: status
    if: false
    input: {result: success, message: 'Selected: ${{ decisions.review.outputs.verdict }}'}

